package com.womclan;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class WomSyncStateTest
{
	private static final long T0 = 1_700_000_000_000L;

	@Test
	public void manualFetchStartsTheCooldown()
	{
		WomSyncState state = new WomSyncState();

		assertTrue(state.beginManualFetch(T0));
		state.recordSuccess(T0 + 500);

		WomSyncStatus status = state.snapshot(T0 + 500);
		assertFalse("a successful fetch must not end the cooldown early", status.isManualSyncAllowed());
		assertEquals(WomSyncState.MANUAL_COOLDOWN_MS - 500, status.getCooldownRemainingMs());
	}

	@Test
	public void manualFetchIsRefusedDuringTheCooldown()
	{
		WomSyncState state = new WomSyncState();
		assertTrue(state.beginManualFetch(T0));
		state.recordSuccess(T0);

		assertFalse(state.beginManualFetch(T0 + WomSyncState.MANUAL_COOLDOWN_MS - 1));
		assertTrue(state.beginManualFetch(T0 + WomSyncState.MANUAL_COOLDOWN_MS));
	}

	@Test
	public void manualFetchIsRefusedWhileAFetchIsRunning()
	{
		WomSyncState state = new WomSyncState();
		assertTrue(state.beginAutoFetch(T0));
		assertFalse(state.beginManualFetch(T0));
		assertFalse(state.snapshot(T0).isManualSyncAllowed());
	}

	@Test
	public void autoFetchDoesNotResetTheManualCooldown()
	{
		WomSyncState state = new WomSyncState();
		assertTrue(state.beginManualFetch(T0));
		state.recordSuccess(T0);

		long later = T0 + 60_000;
		assertTrue(state.beginAutoFetch(later));
		state.recordSuccess(later);

		WomSyncStatus status = state.snapshot(later);
		assertEquals(WomSyncState.MANUAL_COOLDOWN_MS - 60_000, status.getCooldownRemainingMs());
		assertEquals(later, status.getLastSuccessMs());
	}

	@Test
	public void concurrentAutoFetchesAreSkipped()
	{
		WomSyncState state = new WomSyncState();
		assertTrue(state.beginAutoFetch(T0));
		assertFalse(state.beginAutoFetch(T0));
		state.recordSuccess(T0);
		assertTrue(state.beginAutoFetch(T0));
	}

	@Test
	public void failureKeepsTheLastSuccessTimestamp()
	{
		WomSyncState state = new WomSyncState();
		state.beginAutoFetch(T0);
		state.recordSuccess(T0);

		state.beginAutoFetch(T0 + 1_000);
		state.recordFailure("boom");

		WomSyncStatus status = state.snapshot(T0 + 1_000);
		assertEquals(WomSyncState.Outcome.FAILURE, status.getOutcome());
		assertEquals("boom", status.getErrorMessage());
		assertEquals(T0, status.getLastSuccessMs());
		assertFalse(status.isFetching());
	}

	@Test
	public void aClockJumpCannotStrandTheButton()
	{
		WomSyncState state = new WomSyncState();
		assertTrue(state.beginManualFetch(T0));
		state.recordSuccess(T0);

		// System clock moves backwards a day.
		long remaining = state.snapshot(T0 - 86_400_000L).getCooldownRemainingMs();
		assertEquals(WomSyncState.MANUAL_COOLDOWN_MS, remaining);
	}

	@Test
	public void resetForgetsTheGroupButKeepsTheRateLimit()
	{
		WomSyncState state = new WomSyncState();
		assertTrue(state.beginManualFetch(T0));
		state.recordSuccess(T0);

		state.reset();

		WomSyncStatus status = state.snapshot(T0 + 1_000);
		assertEquals(WomSyncState.Outcome.NEVER, status.getOutcome());
		assertFalse(status.hasSucceeded());
		assertEquals(WomSyncState.MANUAL_COOLDOWN_MS - 1_000, status.getCooldownRemainingMs());
	}

	@Test
	public void restoredDeadlinesStillGateRequestsAfterRestart()
	{
		WomSyncState state = new WomSyncState();
		state.restoreDeadlines(T0 + 120_000, T0 + 45_000);

		assertFalse(state.beginManualFetch(T0));
		assertFalse(state.beginAutoFetch(T0));
		assertEquals(120_000, state.snapshot(T0).getCooldownRemainingMs());
		assertTrue(state.beginAutoFetch(T0 + 45_000));
	}

	@Test
	public void serverRetryAfterCanOutlastManualCooldown()
	{
		WomSyncState state = new WomSyncState();
		state.applyRateLimit(new WomRateLimitStatus(20, 0, T0 + 600_000, T0 + 600_000));

		WomSyncStatus status = state.snapshot(T0);
		assertEquals(600_000, status.getCooldownRemainingMs());
		assertEquals(600_000, status.getServerBackoffRemainingMs());
		assertFalse(status.isManualSyncAllowed());
	}

	@Test
	public void cachedDataHasItsOwnOutcome()
	{
		WomSyncState state = new WomSyncState();
		state.recordCached(T0);

		WomSyncStatus status = state.snapshot(T0 + 1_000);
		assertEquals(WomSyncState.Outcome.CACHED, status.getOutcome());
		assertEquals(T0, status.getLastSuccessMs());
	}
}

package com.womclan;

import org.junit.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.assertEquals;

public class WomMemberSortTest
{
	private static final WomMember ALPHA = new WomMember("Alpha", "member", 300, 1.0, 30.0);
	private static final WomMember BRAVO = new WomMember("bravo", "member", 100, 3.0, 20.0);
	private static final WomMember CHARLIE = new WomMember("Charlie", "member", 200, 2.0, 10.0);

	private static List<String> names(List<WomMember> members)
	{
		List<String> names = new ArrayList<>();
		for (WomMember member : members)
		{
			names.add(member.getDisplayName());
		}
		return names;
	}

	private static final List<WomMember> MEMBERS = Arrays.asList(CHARLIE, ALPHA, BRAVO);

	@Test
	public void statSortsAreDescending()
	{
		assertEquals(Arrays.asList("Alpha", "Charlie", "bravo"), names(WomMemberSort.TOTAL_XP.sort(MEMBERS)));
		assertEquals(Arrays.asList("bravo", "Charlie", "Alpha"), names(WomMemberSort.EHP.sort(MEMBERS)));
		assertEquals(Arrays.asList("Alpha", "bravo", "Charlie"), names(WomMemberSort.EHB.sort(MEMBERS)));
	}

	@Test
	public void nameSortIgnoresCase()
	{
		assertEquals(Arrays.asList("Alpha", "bravo", "Charlie"), names(WomMemberSort.NAME.sort(MEMBERS)));
	}

	@Test
	public void tiesBreakByNameSoOrderIsStableAcrossRefreshes()
	{
		WomMember zulu = new WomMember("Zulu", "member", 500, 0.0, 0.0);
		WomMember delta = new WomMember("Delta", "member", 500, 0.0, 0.0);

		assertEquals(Arrays.asList("Delta", "Zulu"), names(WomMemberSort.TOTAL_XP.sort(Arrays.asList(zulu, delta))));
		assertEquals(Arrays.asList("Delta", "Zulu"), names(WomMemberSort.TOTAL_XP.sort(Arrays.asList(delta, zulu))));
	}

	@Test
	public void sortDoesNotMutateTheInputList()
	{
		List<WomMember> original = new ArrayList<>(MEMBERS);
		WomMemberSort.NAME.sort(original);
		assertEquals(names(MEMBERS), names(original));
	}

	@Test
	public void labelsAreShownInTheSelector()
	{
		assertEquals("Total XP", WomMemberSort.TOTAL_XP.toString());
		assertEquals("Name (A-Z)", WomMemberSort.NAME.toString());
	}
}

package com.womclan;

import com.google.gson.Gson;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class WomClanCacheTest
{
	private static final int GROUP_ID = 2300;
	private static final String GROUP_JSON = "{\"name\":\"Cached Clan\",\"memberships\":["
		+ "{\"role\":\"member\",\"player\":{\"username\":\"alpha\",\"exp\":42}}]}";

	@Rule
	public TemporaryFolder temporaryFolder = new TemporaryFolder();

	@Test
	public void groupCacheRestoresMembersWithoutInventingHistory() throws Exception
	{
		WomClanCache cache = new WomClanCache(temporaryFolder.newFolder().toPath(), new Gson());
		cache.storeGroup(GROUP_ID, GROUP_JSON, 1_000);

		WomClanCache.CachedClan cached = cache.load(GROUP_ID);
		assertNotNull(cached);
		assertEquals("Cached Clan", cached.getData().getInfo().getName());
		assertEquals("alpha", cached.getData().getMembers().get(0).getDisplayName());
		assertEquals(WomHistory.Status.PENDING, cached.getData().getAchievements().getStatus());
		assertEquals(1_000, cached.getGroupCachedAtMs());
		assertTrue(cached.historyNeedsRefresh(1_001));
	}

	@Test
	public void completeHistoryCacheHasAnIndependentFreshnessClock() throws Exception
	{
		WomClanCache cache = new WomClanCache(temporaryFolder.newFolder().toPath(), new Gson());
		cache.storeGroup(GROUP_ID, GROUP_JSON, 1_000);
		cache.storeAchievements(GROUP_ID, "[]", 2_000);
		cache.storeActivity(GROUP_ID, "[]", 2_100);
		cache.storeNameChanges(GROUP_ID, "[]", 2_200);

		WomClanCache.CachedClan cached = cache.load(GROUP_ID);
		assertEquals(WomHistory.Status.LOADED, cached.getData().getAchievements().getStatus());
		assertEquals(2_000, cached.getHistoryCachedAtMs());
		assertFalse(cached.historyNeedsRefresh(2_000 + WomClanCache.HISTORY_MAX_AGE_MS - 1));
		assertTrue(cached.historyNeedsRefresh(2_000 + WomClanCache.HISTORY_MAX_AGE_MS));
	}
}

