package com.womclan;

import org.junit.Test;

import java.util.Arrays;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class WomHistoryTest
{
	@Test
	public void loadedCarriesTheEntries()
	{
		WomHistory<String> history = WomHistory.loaded(Arrays.asList("a", "b"));

		assertTrue(history.isAvailable());
		assertEquals(2, history.getEntries().size());
		assertNull(history.getError());
	}

	@Test
	public void anEmptySuccessIsStillAvailable()
	{
		WomHistory<String> history = WomHistory.loaded(Arrays.asList());

		assertTrue("an empty result means no recent events, not a failed fetch", history.isAvailable());
		assertTrue(history.getEntries().isEmpty());
	}

	@Test
	public void unavailableKeepsTheReason()
	{
		WomHistory<String> history = WomHistory.unavailable("WOM API error 503");

		assertFalse(history.isAvailable());
		assertTrue(history.getEntries().isEmpty());
		assertEquals("WOM API error 503", history.getError());
	}

	@Test
	public void pendingIsNeitherLoadedNorFailed()
	{
		WomHistory<String> history = WomHistory.pending();

		assertEquals(WomHistory.Status.PENDING, history.getStatus());
		assertFalse(history.isAvailable());
	}
}

package com.womclan;

import com.google.gson.Gson;
import org.junit.Test;
import org.junit.Rule;
import org.junit.rules.TemporaryFolder;

import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Response;
import okhttp3.ResponseBody;

import java.io.IOException;
import java.time.Instant;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class WomApiClientTest
{
	@Rule
	public TemporaryFolder temporaryFolder = new TemporaryFolder();

	@Test
	public void sidebarFetchUsesOneRequestAndDefersHistory() throws Exception
	{
		AtomicInteger requests = new AtomicInteger();
		OkHttpClient httpClient = new OkHttpClient.Builder().addInterceptor(chain ->
		{
			requests.incrementAndGet();
			return new Response.Builder()
				.request(chain.request())
				.protocol(Protocol.HTTP_1_1)
				.code(200)
				.message("OK")
				.header("RateLimit-Limit", "20")
				.header("RateLimit-Remaining", "19")
				.header("RateLimit-Reset", "60")
				.body(ResponseBody.create(MediaType.parse("application/json"),
					"{\"name\":\"One Request Clan\",\"memberships\":[]}"))
				.build();
		}).build();
		WomApiClient client = new WomApiClient(httpClient,
			new WomClanCache(temporaryFolder.newFolder().toPath(), new Gson()));

		WomClanData data = client.fetchClanData(2300);

		assertEquals(1, requests.get());
		assertEquals(WomHistory.Status.PENDING, data.getAchievements().getStatus());
		assertEquals(20, client.rateLimitStatus().getLimit());
		assertEquals(19, client.rateLimitStatus().getRemaining());
		assertTrue(client.rateLimitStatus().getResetAtMs() > System.currentTimeMillis());
	}

	@Test
	public void parseMembersReadsGroupMemberships() throws IOException
	{
		String json = "{"
			+ "\"id\":2300,"
			+ "\"memberships\":["
			+ "{\"player\":{\"username\":\"alpha\",\"displayName\":\"Alpha\",\"exp\":123,\"ehp\":1.5,\"ehb\":2.5}},"
			+ "{\"player\":{\"username\":\"beta\",\"exp\":456}}"
			+ "]"
			+ "}";

		List<WomMember> members = WomApiClient.parseMembers(json);

		assertEquals(2, members.size());
		assertEquals("Alpha", members.get(0).getDisplayName());
		assertEquals(123L, members.get(0).getTotalXp());
		assertEquals(1.5, members.get(0).getEhp(), 0.0);
		assertEquals(2.5, members.get(0).getEhb(), 0.0);
		assertEquals("beta", members.get(1).getDisplayName());
		assertEquals(456L, members.get(1).getTotalXp());
		assertEquals(0.0, members.get(1).getEhp(), 0.0);
		assertEquals(0.0, members.get(1).getEhb(), 0.0);
	}

	@Test
	public void parseClanInfoReadsMetadataAndTotals() throws IOException
	{
		String json = "{"
			+ "\"id\":2300,"
			+ "\"name\":\"Wise Old Clan\","
			+ "\"clanChat\":\"WOM CC\","
			+ "\"memberCount\":2,"
			+ "\"memberships\":["
			+ "{\"player\":{\"username\":\"alpha\",\"displayName\":\"Alpha\",\"exp\":123,\"ehp\":1.5,\"ehb\":2.5}},"
			+ "{\"player\":{\"username\":\"beta\",\"exp\":456,\"ehp\":3.5,\"ehb\":4.5}}"
			+ "]"
			+ "}";

		List<WomMember> members = WomApiClient.parseMembers(json);
		WomClanInfo info = WomApiClient.parseClanInfo(json, members);

		assertEquals("Wise Old Clan", info.getName());
		assertEquals("WOM CC", info.getClanChat());
		assertEquals(2, info.getMemberCount());
		assertEquals(579L, info.getTotalXp());
		assertEquals(5.0, info.getTotalEhp(), 0.0);
		assertEquals(7.0, info.getTotalEhb(), 0.0);
	}

	@Test
	public void parseAchievementsReadsRecentMilestones() throws IOException
	{
		String json = "["
			+ "{"
			+ "\"name\":\"Base 70 Stats\","
			+ "\"metric\":\"overall\","
			+ "\"threshold\":737627,"
			+ "\"measure\":\"levels\","
			+ "\"createdAt\":\"2022-10-28T12:42:24.215Z\","
			+ "\"player\":{\"username\":\"alpha\",\"displayName\":\"Alpha\"}"
			+ "}"
			+ "]";

		List<WomAchievement> achievements = WomApiClient.parseAchievements(json);

		assertEquals(1, achievements.size());
		assertEquals("Alpha", achievements.get(0).getDisplayName());
		assertEquals("Base 70 Stats", achievements.get(0).getName());
		assertEquals("overall", achievements.get(0).getMetric());
		assertEquals("levels", achievements.get(0).getMeasure());
		assertEquals(737627L, achievements.get(0).getThreshold());
		assertEquals(Instant.parse("2022-10-28T12:42:24.215Z"), achievements.get(0).getCreatedAt());
	}

	@Test
	public void parseActivityReadsMembershipChanges() throws IOException
	{
		String json = "["
			+ "{"
			+ "\"type\":\"joined\","
			+ "\"role\":null,"
			+ "\"createdAt\":\"2023-10-16T13:20:50.273Z\","
			+ "\"player\":{\"username\":\"beta\",\"displayName\":\"Beta\"}"
			+ "},"
			+ "{"
			+ "\"type\":\"changed_role\","
			+ "\"role\":\"iron\","
			+ "\"createdAt\":\"2023-10-23T20:39:45.104Z\","
			+ "\"player\":{\"username\":\"gamma\"}"
			+ "}"
			+ "]";

		List<WomGroupActivity> activity = WomApiClient.parseActivity(json);

		assertEquals(2, activity.size());
		assertEquals("Beta", activity.get(0).getDisplayName());
		assertEquals("joined", activity.get(0).getType());
		assertEquals("", activity.get(0).getRole());
		assertEquals(Instant.parse("2023-10-16T13:20:50.273Z"), activity.get(0).getCreatedAt());
		assertEquals("gamma", activity.get(1).getDisplayName());
		assertEquals("changed_role", activity.get(1).getType());
		assertEquals("iron", activity.get(1).getRole());
	}

	@Test
	public void parseNameChangesReadsRecentGroupNameChanges() throws IOException
	{
		String json = "["
			+ "{"
			+ "\"oldName\":\"Old Alpha\","
			+ "\"newName\":\"New Alpha\","
			+ "\"status\":\"approved\","
			+ "\"resolvedAt\":\"2024-01-02T03:04:05.000Z\","
			+ "\"createdAt\":\"2024-01-01T03:04:05.000Z\","
			+ "\"player\":{\"username\":\"new alpha\",\"displayName\":\"New Alpha\"}"
			+ "},"
			+ "{"
			+ "\"oldName\":\"Old Beta\","
			+ "\"newName\":\"New Beta\","
			+ "\"status\":\"pending\","
			+ "\"resolvedAt\":null,"
			+ "\"createdAt\":\"2024-02-01T03:04:05.000Z\""
			+ "}"
			+ "]";

		List<WomNameChange> nameChanges = WomApiClient.parseNameChanges(json);

		assertEquals(2, nameChanges.size());
		assertEquals("New Alpha", nameChanges.get(0).getDisplayName());
		assertEquals("Old Alpha", nameChanges.get(0).getOldName());
		assertEquals("New Alpha", nameChanges.get(0).getNewName());
		assertEquals("approved", nameChanges.get(0).getStatus());
		assertEquals(Instant.parse("2024-01-02T03:04:05.000Z"), nameChanges.get(0).getResolvedAt());
		assertEquals(Instant.parse("2024-01-01T03:04:05.000Z"), nameChanges.get(0).getCreatedAt());
		assertEquals("New Beta", nameChanges.get(1).getDisplayName());
		assertEquals("pending", nameChanges.get(1).getStatus());
	}
}

package com.womclan;

import org.junit.Test;

import java.awt.Dimension;
import java.awt.Rectangle;
import java.util.Arrays;
import java.util.Collections;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class WomWindowGeometryTest
{
	private static final Dimension MINIMUM = new Dimension(620, 380);

	@Test
	public void preservesBoundsOnMonitorToLeftOfPrimary()
	{
		Rectangle saved = new Rectangle(-1600, 120, 850, 560);
		assertEquals(saved, WomWindowGeometry.fitToScreens(saved, MINIMUM, Arrays.asList(
			new Rectangle(0, 30, 1920, 1050), new Rectangle(-1920, 0, 1920, 1080))));
		assertEquals(saved, WomWindowGeometry.decode(WomWindowGeometry.encode(saved)));
	}

	@Test
	public void bringsWindowBackAfterMonitorIsDisconnected()
	{
		assertEquals(new Rectangle(1070, 100, 850, 560), WomWindowGeometry.fitToScreens(
			new Rectangle(2400, 100, 850, 560), MINIMUM,
			Collections.singletonList(new Rectangle(0, 30, 1920, 1050))));
	}

	@Test
	public void fitsOversizedWindowToSmallWorkAreaIncludingReservedBar()
	{
		Rectangle workArea = new Rectangle(0, 40, 500, 300);
		assertEquals(workArea, WomWindowGeometry.fitToScreens(
			new Rectangle(-100, -100, 1600, 1200), MINIMUM, Collections.singletonList(workArea)));
	}

	@Test
	public void selectsMonitorWithLargestOverlap()
	{
		assertEquals(new Rectangle(1920, 100, 850, 560), WomWindowGeometry.fitToScreens(
			new Rectangle(1800, 100, 850, 560), MINIMUM, Arrays.asList(
				new Rectangle(0, 0, 1920, 1080), new Rectangle(1920, 0, 1920, 1080))));
	}

	@Test
	public void selectsNearestMonitorWhenSavedWindowIsInGap()
	{
		assertEquals(new Rectangle(1100, 40, 620, 380), WomWindowGeometry.fitToScreens(
			new Rectangle(950, 40, 100, 100), MINIMUM, Arrays.asList(
				new Rectangle(0, 0, 800, 600), new Rectangle(1100, 0, 800, 600))));
	}

	@Test
	public void restoresMinimumSizeAndKeepsTitleBarBelowReservedArea()
	{
		assertEquals(new Rectangle(100, 40, 620, 380), WomWindowGeometry.fitToScreens(
			new Rectangle(100, -50, 100, 100), MINIMUM,
			Collections.singletonList(new Rectangle(0, 40, 1920, 1040))));
	}

	@Test
	public void rejectsMalformedOrUnusableSavedBounds()
	{
		for (String value : Arrays.asList(null, "", "1,2,3", "1,2,3,4,", "a,2,3,4",
			"0,0,0,560", "0,0,850,-1", "999999999999,0,850,560"))
		{
			assertNull(value, WomWindowGeometry.decode(value));
		}
	}
}

package com.womclan;

import org.junit.Test;

import java.time.Instant;
import java.time.ZoneId;
import java.time.ZonedDateTime;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class WomFormatTest
{
	private static WomAchievement achievement(String name, String metric, String measure, long threshold)
	{
		return new WomAchievement("Player", name, metric, measure, threshold, Instant.EPOCH);
	}

	@Test
	public void achievementValueRendersExperienceThresholds()
	{
		assertEquals("13,034,431 XP",
			WomFormat.achievementValue(achievement("99 Attack", "attack", "experience", 13_034_431L)));
	}

	@Test
	public void achievementValueRendersKillCounts()
	{
		assertEquals("1,000 kills",
			WomFormat.achievementValue(achievement("1k Kraken kills", "kraken", "kills", 1_000L)));
		assertEquals("1 kill",
			WomFormat.achievementValue(achievement("First Kraken kill", "kraken", "kills", 1L)));
	}

	@Test
	public void achievementValueKeepsPlausibleLevelCounts()
	{
		assertEquals("1,250 levels",
			WomFormat.achievementValue(achievement("1250 Total", "overall", "levels", 1_250L)));
	}

	@Test
	public void achievementValueTreatsImplausibleLevelCountAsExperience()
	{
		// "Base 90 Stats" reports a levels measure against an experience threshold; rendering the
		// two together produced "128,311,968 levels".
		assertEquals("128,311,968 XP",
			WomFormat.achievementValue(achievement("Base 90 Stats", "overall", "levels", 128_311_968L)));
	}

	@Test
	public void achievementValueIsEmptyWithoutAThreshold()
	{
		assertEquals("", WomFormat.achievementValue(achievement("Something", "overall", "experience", 0L)));
	}

	@Test
	public void achievementDetailCombinesMetricAndValue()
	{
		assertEquals("Kraken — 1,000 kills",
			WomFormat.achievementDetail(achievement("1k Kraken kills", "kraken", "kills", 1_000L)));
		assertEquals("Overall",
			WomFormat.achievementDetail(achievement("Maxed", "overall", "experience", 0L)));
		assertNull(WomFormat.achievementDetail(achievement("Mystery", "", "", 0L)));
	}

	@Test
	public void titleCaseNormalisesApiTokens()
	{
		assertEquals("Deputy Owner", WomFormat.titleCase("deputy_owner"));
		assertEquals("Changed Role", WomFormat.titleCase("changed_role"));
		assertEquals("", WomFormat.titleCase(null));
	}

	@Test
	public void roleFallsBackToMember()
	{
		assertEquals("Member", WomFormat.role(null));
		assertEquals("Member", WomFormat.role(""));
		assertEquals("Gold", WomFormat.role("gold"));
	}

	private static final ZoneId UTC = ZoneId.of("UTC");

	private static long utc(int year, int month, int day, int hour, int minute)
	{
		return ZonedDateTime.of(year, month, day, hour, minute, 0, 0, UTC).toInstant().toEpochMilli();
	}

	@Test
	public void countdownRoundsUpSoItNeverReadsZeroWhileWaiting()
	{
		assertEquals("5:00", WomFormat.countdown(5 * 60 * 1_000L));
		assertEquals("4:32", WomFormat.countdown(4 * 60_000L + 31_500L));
		assertEquals("0:01", WomFormat.countdown(1));
		assertEquals("0:00", WomFormat.countdown(0));
	}

	@Test
	public void sinceReportsElapsedMinutesWhileRecent()
	{
		long now = utc(2026, 9, 9, 14, 30);
		assertEquals("just now", WomFormat.since(now - 59_000, now, UTC));
		assertEquals("1 min ago", WomFormat.since(now - 60_000, now, UTC));
		assertEquals("23 mins ago", WomFormat.since(now - 23 * 60_000, now, UTC));
	}

	@Test
	public void sinceFallsBackToAClockTimeOnceElapsedStopsHelping()
	{
		long now = utc(2026, 9, 9, 14, 30);
		assertEquals("at 12:15", WomFormat.since(utc(2026, 9, 9, 12, 15), now, UTC));
		assertEquals("on 8 Sep 23:05", WomFormat.since(utc(2026, 9, 8, 23, 5), now, UTC));
	}

	@Test
	public void sinceHandlesNeverSynced()
	{
		assertEquals("never", WomFormat.since(0, utc(2026, 9, 9, 14, 30), UTC));
	}

	@Test
	public void timestampKeepsTheExactValueDiscoverable()
	{
		assertEquals("2026-09-09 14:30:00", WomFormat.timestamp(utc(2026, 9, 9, 14, 30), UTC));
		assertEquals("", WomFormat.timestamp(0, UTC));
	}

	@Test
	public void historyStatusSeparatesEmptyFromUnavailable()
	{
		assertEquals("No recent name changes.",
			WomFormat.historyStatus(WomHistory.Status.LOADED, 0, 0, "", "name changes"));
		assertEquals("Could not load name changes.",
			WomFormat.historyStatus(WomHistory.Status.UNAVAILABLE, 0, 0, "", "name changes"));
		assertEquals("Loading name changes…",
			WomFormat.historyStatus(WomHistory.Status.PENDING, 0, 0, "", "name changes"));
		assertEquals("Showing 1,200 recent achievements.",
			WomFormat.historyStatus(WomHistory.Status.LOADED, 1200, 1200, "", "achievements"));
	}

	@Test
	public void historyStatusSeparatesNoMatchesFromNoEvents()
	{
		assertEquals("No achievements match \"zezima\".",
			WomFormat.historyStatus(WomHistory.Status.LOADED, 50, 0, "zezima", "achievements"));
		assertEquals("Showing 3 of 50 recent achievements.",
			WomFormat.historyStatus(WomHistory.Status.LOADED, 50, 3, "woox", "achievements"));
	}

	@Test
	public void historyStatusReportsFailureAheadOfAnyQuery()
	{
		assertEquals("Could not load activity.",
			WomFormat.historyStatus(WomHistory.Status.UNAVAILABLE, 0, 0, "woox", "activity"));
	}

	@Test
	public void relativeDatesCoarsenAsEventsAge()
	{
		long now = utc(2026, 9, 9, 14, 30);
		assertEquals("", WomFormat.relative(null, now, UTC));
		assertEquals("just now", WomFormat.relative(instantAt(2026, 9, 9, 14, 30), now, UTC));
		assertEquals("45m ago", WomFormat.relative(instantAt(2026, 9, 9, 13, 45), now, UTC));
		assertEquals("5h ago", WomFormat.relative(instantAt(2026, 9, 9, 9, 30), now, UTC));
		assertEquals("3d ago", WomFormat.relative(instantAt(2026, 9, 6, 14, 30), now, UTC));
		assertEquals("8 Sep 2025", WomFormat.relative(instantAt(2025, 9, 8, 14, 30), now, UTC));
	}

	@Test
	public void exactMomentBacksTheRelativeDate()
	{
		assertEquals("Tue 8 Sep 2026, 14:22", WomFormat.exactMoment(instantAt(2026, 9, 8, 14, 22), UTC));
		assertEquals("", WomFormat.exactMoment(null, UTC));
	}

	private static Instant instantAt(int year, int month, int day, int hour, int minute)
	{
		return Instant.ofEpochMilli(utc(year, month, day, hour, minute));
	}

	private static WomSyncStatus status(WomSyncState.Outcome outcome, boolean fetching, long lastSuccessMs, long cooldownMs)
	{
		return new WomSyncStatus(outcome, fetching, null, lastSuccessMs, cooldownMs);
	}

	@Test
	public void syncButtonTextCarriesTheWaitOnTheControl()
	{
		assertEquals("Syncing…", WomFormat.syncButtonText(status(WomSyncState.Outcome.SUCCESS, true, 1, 0), "Sync Now"));
