package com.womclan;

import lombok.Value;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * One optional history section (achievements, activity, name changes) together with whether it
 * could actually be fetched.
 *
 * <p>These sections are fetched best-effort, so a failure used to be flattened into an empty list —
 * which made "the API did not answer" indistinguishable from "this clan has had no recent events".
 * Carrying the status alongside the entries lets each surface say which one it is.</p>
 */
@Value
class WomHistory<T>
{
	enum Status
	{
		/** Never fetched: no attempt has completed yet. */
		PENDING,
		/** Fetched successfully. The entries may still legitimately be empty. */
		LOADED,
		/** The fetch failed; {@link #error} says how. */
		UNAVAILABLE
	}

	Status status;
	List<T> entries;
	String error;

	static <T> WomHistory<T> pending()
	{
		return new WomHistory<>(Status.PENDING, Collections.emptyList(), null);
	}

	static <T> WomHistory<T> loaded(List<T> entries)
	{
		return new WomHistory<>(Status.LOADED, new ArrayList<>(entries), null);
	}

	static <T> WomHistory<T> unavailable(String error)
	{
		return new WomHistory<>(Status.UNAVAILABLE, Collections.emptyList(), error);
	}

	boolean isAvailable()
	{
		return status == Status.LOADED;
	}
}

package com.womclan;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

import javax.inject.Inject;
import java.io.IOException;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;

@Slf4j
public class WomApiClient
{
	private static final String API_BASE = "https://api.wiseoldman.net/v2";
	/** How many history entries each optional section fetches. The UI names this, so it is shared. */
	static final int HISTORY_LIMIT = 50;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private WomClanCache cache;

	private volatile WomRateLimitStatus rateLimitStatus = WomRateLimitStatus.UNKNOWN;

	public WomApiClient()
	{
	}

	/** Test seam for exercising the complete request path without dependency injection. */
	WomApiClient(OkHttpClient okHttpClient, WomClanCache cache)
	{
		this.okHttpClient = okHttpClient;
		this.cache = cache;
	}

	/** Fetches the one response needed by the sidebar. History is restored from cache, if present. */
	public WomClanData fetchClanData(int groupId) throws IOException
	{
		String body = fetchBody(API_BASE + "/groups/" + groupId, "group " + groupId);
		long now = System.currentTimeMillis();
		cache.storeGroup(groupId, body, now);
		List<WomMember> members = parseMembers(body);
		WomClanCache.CachedClan cached = cache.load(groupId);

		log.debug("Fetched {} members for group {}", members.size(), groupId);
		return new WomClanData(
			groupId,
			parseClanInfo(body, members),
			members,
			cached == null ? WomHistory.pending() : cached.getData().getAchievements(),
			cached == null ? WomHistory.pending() : cached.getData().getActivity(),
			cached == null ? WomHistory.pending() : cached.getData().getNameChanges()
		);
	}

	/** Restores the most recent successful response immediately, without touching the network. */
	WomClanCache.CachedClan loadCachedClanData(int groupId)
	{
		return cache.load(groupId);
	}

	/**
	 * Fetches the optional detail feeds. This is called only when Clan Details needs them, rather
	 * than spending three requests on every sidebar refresh.
	 */
	WomClanData fetchClanHistory(int groupId, WomClanData base) throws IOException
	{
		WomHistory<WomAchievement> achievements = fetchHistory(groupId, "achievements", () ->
		{
			String body = fetchBody(API_BASE + "/groups/" + groupId + "/achievements?limit=" + HISTORY_LIMIT,
				"group achievements " + groupId);
			cache.storeAchievements(groupId, body, System.currentTimeMillis());
			return parseAchievements(body);
		});

		WomHistory<WomGroupActivity> activity = fetchHistory(groupId, "activity", () ->
		{
			String body = fetchBody(API_BASE + "/groups/" + groupId + "/activity?limit=" + HISTORY_LIMIT,
				"group activity " + groupId);
			cache.storeActivity(groupId, body, System.currentTimeMillis());
			return parseActivity(body);
		});

		WomHistory<WomNameChange> nameChanges = fetchHistory(groupId, "name changes", () ->
		{
			String body = fetchBody(API_BASE + "/groups/" + groupId + "/name-changes?limit=" + HISTORY_LIMIT,
				"group name changes " + groupId);
			cache.storeNameChanges(groupId, body, System.currentTimeMillis());
			return parseNameChanges(body);
		});

		return new WomClanData(groupId, base.getInfo(), base.getMembers(), achievements, activity, nameChanges);
	}

	WomRateLimitStatus rateLimitStatus()
	{
		return rateLimitStatus;
	}

	/**
	 * Fetches all members of a WOM group and their stats.
	 *
	 * @param groupId the Wise Old Man group ID
	 * @return list of WomMember, sorted by the caller
	 * @throws IOException on network or non-2xx response
	 */
	public List<WomMember> fetchMembers(int groupId) throws IOException
	{
		String body = fetchBody(API_BASE + "/groups/" + groupId, "group " + groupId);
		List<WomMember> members = parseMembers(body);

		log.debug("Fetched {} members for group {}", members.size(), groupId);
		return members;
	}

	public List<WomAchievement> fetchAchievements(int groupId) throws IOException
	{
		String body = fetchBody(
			API_BASE + "/groups/" + groupId + "/achievements?limit=" + HISTORY_LIMIT,
			"group achievements " + groupId
		);
		List<WomAchievement> achievements = parseAchievements(body);

		log.debug("Fetched {} achievements for group {}", achievements.size(), groupId);
		return achievements;
	}

	public List<WomGroupActivity> fetchActivity(int groupId) throws IOException
	{
		String body = fetchBody(
			API_BASE + "/groups/" + groupId + "/activity?limit=" + HISTORY_LIMIT,
			"group activity " + groupId
		);
		List<WomGroupActivity> activity = parseActivity(body);

		log.debug("Fetched {} activity entries for group {}", activity.size(), groupId);
		return activity;
	}

	public List<WomNameChange> fetchNameChanges(int groupId) throws IOException
	{
		String body = fetchBody(
			API_BASE + "/groups/" + groupId + "/name-changes?limit=" + HISTORY_LIMIT,
			"group name changes " + groupId
		);
		List<WomNameChange> nameChanges = parseNameChanges(body);

		log.debug("Fetched {} name changes for group {}", nameChanges.size(), groupId);
		return nameChanges;
	}

	/**
	 * Runs one best-effort history fetch. These sections are optional — a member list is still worth
	 * showing without them — but a failure is recorded rather than flattened into an empty list, so
	 * the UI can tell "could not load" apart from "nothing happened recently".
	 */
	private <T> WomHistory<T> fetchHistory(int groupId, String noun, HistoryFetch<T> fetch) throws IOException
	{
		try
		{
			return WomHistory.loaded(fetch.run());
		}
		catch (IOException e)
		{
			// A 429 establishes a server deadline. Let the caller stop the detail sequence instead
			// of turning it into three immediate rejected requests.
			if (e instanceof WomApiException && ((WomApiException) e).getStatusCode() == 429)
			{
				throw e;
			}
			log.warn("WOM Clan Stats: failed to fetch {} for group {}: {}", noun, groupId, e.getMessage());
			return WomHistory.unavailable(e.getMessage());
		}
	}

	@FunctionalInterface
	private interface HistoryFetch<T>
	{
		List<T> run() throws IOException;
	}

	static List<WomMember> parseMembers(String body) throws IOException
	{
		JsonObject root = new JsonParser().parse(body).getAsJsonObject();
		JsonArray memberships = root.has("memberships") && root.get("memberships").isJsonArray()
			? root.getAsJsonArray("memberships")
			: new JsonArray();

		List<WomMember> members = new ArrayList<>();
		for (JsonElement elem : memberships)
		{
			JsonObject obj = elem.getAsJsonObject();
			if (!obj.has("player") || obj.get("player").isJsonNull())
			{
				continue;
			}

			JsonObject player = obj.getAsJsonObject("player");
			if (!player.has("username") || player.get("username").isJsonNull())
			{
				continue;
			}

			String displayName = player.has("displayName") && !player.get("displayName").isJsonNull()
				? player.get("displayName").getAsString()
				: player.get("username").getAsString();

			String role = obj.has("role") && !obj.get("role").isJsonNull()
				? obj.get("role").getAsString()
				: "member";

			long totalXp = player.has("exp") && !player.get("exp").isJsonNull()
				? player.get("exp").getAsLong()
				: 0L;

			double ehp = player.has("ehp") && !player.get("ehp").isJsonNull()
				? player.get("ehp").getAsDouble()
				: 0.0;

			double ehb = player.has("ehb") && !player.get("ehb").isJsonNull()
				? player.get("ehb").getAsDouble()
				: 0.0;

			members.add(new WomMember(displayName, role, totalXp, ehp, ehb));
		}

		return members;
	}

	static WomClanInfo parseClanInfo(String body, List<WomMember> members) throws IOException
	{
		JsonObject root = new JsonParser().parse(body).getAsJsonObject();
		String name = readString(root, "name", "Clan");
		String clanChat = readString(root, "clanChat", "");
		int memberCount = root.has("memberCount") && !root.get("memberCount").isJsonNull()
			? root.get("memberCount").getAsInt()
			: members.size();

		long totalXp = 0L;
		double totalEhp = 0.0;
		double totalEhb = 0.0;
		for (WomMember member : members)
		{
			totalXp += member.getTotalXp();
			totalEhp += member.getEhp();
			totalEhb += member.getEhb();
		}

		return new WomClanInfo(name, clanChat, memberCount, totalXp, totalEhp, totalEhb);
	}

	static List<WomAchievement> parseAchievements(String body) throws IOException
	{
		JsonArray root = new JsonParser().parse(body).getAsJsonArray();

		List<WomAchievement> achievements = new ArrayList<>();
		for (JsonElement elem : root)
		{
			JsonObject obj = elem.getAsJsonObject();
			String displayName = readPlayerDisplayName(obj);
			if (displayName == null)
			{
				continue;
			}

			achievements.add(new WomAchievement(
				displayName,
				readString(obj, "name", "Achievement"),
				readString(obj, "metric", ""),
				readString(obj, "measure", ""),
				readLong(obj, "threshold", 0L),
				readInstant(obj, "createdAt")
			));
		}

		return achievements;
	}

	static List<WomGroupActivity> parseActivity(String body) throws IOException
	{
		JsonArray root = new JsonParser().parse(body).getAsJsonArray();

		List<WomGroupActivity> activity = new ArrayList<>();
		for (JsonElement elem : root)
		{
			JsonObject obj = elem.getAsJsonObject();
			String displayName = readPlayerDisplayName(obj);
			if (displayName == null)
			{
				continue;
			}

			activity.add(new WomGroupActivity(
				displayName,
				readString(obj, "type", ""),
				readString(obj, "role", ""),
				readInstant(obj, "createdAt")
			));
		}

		return activity;
	}

	static List<WomNameChange> parseNameChanges(String body) throws IOException
	{
		JsonArray root = new JsonParser().parse(body).getAsJsonArray();

		List<WomNameChange> nameChanges = new ArrayList<>();
		for (JsonElement elem : root)
		{
			JsonObject obj = elem.getAsJsonObject();
			String oldName = readString(obj, "oldName", "");
			String newName = readString(obj, "newName", "");
			String displayName = readPlayerDisplayName(obj);
			if (displayName == null)
			{
				displayName = newName.isEmpty() ? oldName : newName;
			}

			nameChanges.add(new WomNameChange(
				displayName,
				oldName,
				newName,
				readString(obj, "status", ""),
				readInstant(obj, "resolvedAt"),
				readInstant(obj, "createdAt")
			));
		}

		return nameChanges;
	}

	private String fetchBody(String url, String context) throws IOException
	{
		long now = System.currentTimeMillis();
		if (rateLimitStatus.getRetryAtMs() > now)
		{
			throw new WomApiException("WOM API retry available later", 429, rateLimitStatus.getRetryAtMs());
		}

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", "WomClanStats-RuneLitePlugin/1.0")
			.build();

		try (Response response = okHttpClient.newCall(request).execute())
		{
			captureRateLimit(response, System.currentTimeMillis());
			if (!response.isSuccessful())
			{
				throw new WomApiException(
					"WOM API error " + response.code() + " for " + context,
					response.code(),
					rateLimitStatus.getRetryAtMs());
			}

			ResponseBody responseBody = response.body();
			if (responseBody == null)
			{
				throw new IOException("Empty response body from WOM API for " + context);
			}

			return responseBody.string();
		}
	}

	private void captureRateLimit(Response response, long nowMs)
	{
		int limit = headerInt(response, "RateLimit-Limit", -1);
		int remaining = headerInt(response, "RateLimit-Remaining", -1);
		long resetAt = deadline(nowMs, headerInt(response, "RateLimit-Reset", 0));
		long retryAt = deadline(nowMs, headerInt(response, "Retry-After", 0));
		// The last permitted response has no Retry-After yet, but Remaining: 0 already tells us
		// that another request in this window would be rejected.
		if (remaining == 0 && retryAt == 0)
		{
			retryAt = resetAt;
		}
		rateLimitStatus = new WomRateLimitStatus(limit, remaining, resetAt, retryAt);
	}

	private static int headerInt(Response response, String name, int defaultValue)
	{
		String value = response.header(name);
		if (value == null)
		{
			return defaultValue;
		}
		try
		{
			return Integer.parseInt(value);
		}
		catch (NumberFormatException e)
		{
			return defaultValue;
		}
	}

	private static long deadline(long nowMs, int seconds)
	{
		return seconds <= 0 ? 0 : nowMs + seconds * 1_000L;
	}

	private static String readPlayerDisplayName(JsonObject obj)
	{
		if (!obj.has("player") || obj.get("player").isJsonNull())
		{
			return null;
		}

		JsonObject player = obj.getAsJsonObject("player");
		if (!player.has("username") || player.get("username").isJsonNull())
		{
			return null;
		}

		return player.has("displayName") && !player.get("displayName").isJsonNull()
			? player.get("displayName").getAsString()
			: player.get("username").getAsString();
	}

	private static String readString(JsonObject obj, String field, String defaultValue)
	{
		return obj.has(field) && !obj.get(field).isJsonNull()
			? obj.get(field).getAsString()
			: defaultValue;
	}

	private static long readLong(JsonObject obj, String field, long defaultValue)
	{
		return obj.has(field) && !obj.get(field).isJsonNull()
			? obj.get(field).getAsLong()
			: defaultValue;
	}

	private static Instant readInstant(JsonObject obj, String field)
	{
		if (!obj.has(field) || obj.get(field).isJsonNull())
		{
			return null;
		}

		try
		{
			return Instant.parse(obj.get(field).getAsString());
		}
		catch (DateTimeParseException e)
		{
			return null;
		}
	}
}

package com.womclan;

/**
 * The single source of truth for refresh state: whether a fetch is in flight, when the last one
 * succeeded, and how much of the manual cooldown is left.
 *
 * <p>Owned by {@link WomClanPlugin} rather than by a panel so every surface that offers a refresh
 * shares one cooldown instead of inventing its own. Mutated from the fetch executor and read from
 * the EDT, hence the synchronisation; readers take an immutable {@link WomSyncStatus} snapshot so
 * they cannot observe a half-updated state.</p>
 */
class WomSyncState
{
	/** Manual refreshes are limited to one per this interval, to stay friendly to the WOM API. */
	static final long MANUAL_COOLDOWN_MS = 5 * 60 * 1_000L;

	enum Outcome
	{
		NEVER,
		CACHED,
		SUCCESS,
		FAILURE,
		NOT_CONFIGURED
	}

	private long manualAllowedAtMs;
	private long serverRetryAtMs;
	private long lastSuccessMs;
	private int rateLimit = -1;
	private int rateRemaining = -1;
	private long rateResetAtMs;
	private boolean fetching;
	private Outcome outcome = Outcome.NEVER;
	private String errorMessage;

	/**
	 * Claims the right to start a user-requested fetch, starting the manual cooldown.
	 *
	 * @return false when a fetch is already running or the cooldown has not elapsed
	 */
	synchronized boolean beginManualFetch(long now)
	{
		if (fetching || cooldownRemaining(now) > 0)
		{
			return false;
		}

		manualAllowedAtMs = now + MANUAL_COOLDOWN_MS;
		fetching = true;
		return true;
	}

	/**
	 * Claims the right to start an automatic fetch. Deliberately leaves the manual cooldown alone:
	 * an hourly refresh should neither extend nor clear the user's own five-minute budget.
	 *
	 * @return false when a fetch is already running
	 */
	synchronized boolean beginAutoFetch(long now)
	{
		if (fetching || serverRetryAtMs > now)
		{
			return false;
		}

		fetching = true;
		return true;
	}

	/** Seeds the panel with disk-cached data while a network refresh is pending. */
	synchronized void recordCached(long cachedAtMs)
	{
		if (lastSuccessMs == 0)
		{
			lastSuccessMs = cachedAtMs;
			outcome = Outcome.CACHED;
		}
	}

	/** Restores gates that must survive a plugin or RuneLite restart. */
	synchronized void restoreDeadlines(long manualAllowedAtMs, long serverRetryAtMs)
	{
		this.manualAllowedAtMs = Math.max(0, manualAllowedAtMs);
		this.serverRetryAtMs = Math.max(0, serverRetryAtMs);
	}

	/** Applies the authoritative request budget and backoff returned by WOM. */
	synchronized void applyRateLimit(WomRateLimitStatus status)
	{
		if (status == null)
		{
			return;
		}
		rateLimit = status.getLimit();
		rateRemaining = status.getRemaining();
		rateResetAtMs = status.getResetAtMs();
		serverRetryAtMs = Math.max(serverRetryAtMs, status.getRetryAtMs());
	}

	synchronized void recordSuccess(long now)
	{
		fetching = false;
		lastSuccessMs = now;
		outcome = Outcome.SUCCESS;
		errorMessage = null;
	}

	synchronized void recordFailure(String error)
	{
		fetching = false;
		outcome = Outcome.FAILURE;
		errorMessage = error;
	}

	synchronized void recordNotConfigured()
	{
		fetching = false;
		outcome = Outcome.NOT_CONFIGURED;
		errorMessage = null;
	}

	/** Forgets everything but the manual cooldown, which is a rate limit rather than group state. */
	synchronized void reset()
	{
		lastSuccessMs = 0;
		outcome = Outcome.NEVER;
		errorMessage = null;
	}

	synchronized WomSyncStatus snapshot(long now)
	{
		return new WomSyncStatus(outcome, fetching, errorMessage, lastSuccessMs, cooldownRemaining(now),
			rateLimit, rateRemaining, rateResetAtMs, Math.max(0, serverRetryAtMs - now));
	}

	synchronized long getManualAllowedAtMs()
	{
		return manualAllowedAtMs;
	}

	synchronized long getServerRetryAtMs()
	{
		return serverRetryAtMs;
	}

	private long cooldownRemaining(long now)
	{
		// Clamped on both ends so a system clock that jumps cannot strand the button.
		long manualRemaining = Math.max(0, Math.min(MANUAL_COOLDOWN_MS, manualAllowedAtMs - now));
		long serverRemaining = Math.max(0, serverRetryAtMs - now);
		return Math.max(manualRemaining, serverRemaining);
	}
}

package com.womclan;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;

/**
 * Small disk cache of raw WOM responses. Raw JSON avoids coupling the on-disk format to the UI
 * model and lets the normal, tested API parsers validate every restored response.
 */
@Slf4j
@Singleton
class WomClanCache
{
	static final long HISTORY_MAX_AGE_MS = 60 * 60 * 1_000L;

	private final Path directory;
	private final Gson gson;

	@Inject
	WomClanCache(Gson gson)
	{
		this(new File(RuneLite.RUNELITE_DIR, "wom-clan-stats").toPath(), gson);
	}

	WomClanCache(Path directory, Gson gson)
	{
		this.directory = directory;
		this.gson = gson;
	}

	synchronized CachedClan load(int groupId)
	{
		Record record = read(groupId);
		if (record == null || record.groupBody == null || record.groupBody.isEmpty())
		{
			return null;
		}

		try
		{
			java.util.List<WomMember> members = WomApiClient.parseMembers(record.groupBody);
			WomClanData data = new WomClanData(
				groupId,
				WomApiClient.parseClanInfo(record.groupBody, members),
				members,
				parseHistory(record.achievementsBody, WomApiClient::parseAchievements),
				parseHistory(record.activityBody, WomApiClient::parseActivity),
				parseHistory(record.nameChangesBody, WomApiClient::parseNameChanges)
			);
			long oldestHistoryMs = oldestPresent(
				record.achievementsAtMs, record.activityAtMs, record.nameChangesAtMs);
			return new CachedClan(data, record.groupAtMs, oldestHistoryMs);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("WOM Clan Stats: ignoring unreadable cache for group {}: {}", groupId, e.getMessage());
			return null;
		}
	}

	synchronized void storeGroup(int groupId, String body, long nowMs)
	{
		Record record = readOrNew(groupId);
		record.groupBody = body;
		record.groupAtMs = nowMs;
		write(groupId, record);
	}

	synchronized void storeAchievements(int groupId, String body, long nowMs)
	{
		Record record = readOrNew(groupId);
		record.achievementsBody = body;
		record.achievementsAtMs = nowMs;
		write(groupId, record);
	}

	synchronized void storeActivity(int groupId, String body, long nowMs)
	{
		Record record = readOrNew(groupId);
		record.activityBody = body;
		record.activityAtMs = nowMs;
		write(groupId, record);
	}

	synchronized void storeNameChanges(int groupId, String body, long nowMs)
	{
		Record record = readOrNew(groupId);
		record.nameChangesBody = body;
		record.nameChangesAtMs = nowMs;
		write(groupId, record);
	}

	private Record readOrNew(int groupId)
	{
		Record record = read(groupId);
		return record == null ? new Record() : record;
	}

	private Record read(int groupId)
	{
		Path file = file(groupId);
		if (!Files.isRegularFile(file))
		{
			return null;
		}

		try
		{
			return gson.fromJson(new String(Files.readAllBytes(file), StandardCharsets.UTF_8), Record.class);
		}
		catch (IOException | JsonParseException e)
		{
			log.warn("WOM Clan Stats: could not read cache for group {}: {}", groupId, e.getMessage());
			return null;
		}
	}

	private void write(int groupId, Record record)
	{
		try
		{
			Files.createDirectories(directory);
			Path temporary = Files.createTempFile(directory, "group-" + groupId + "-", ".tmp");
			Files.write(temporary, gson.toJson(record).getBytes(StandardCharsets.UTF_8));
			try
			{
				Files.move(temporary, file(groupId), StandardCopyOption.ATOMIC_MOVE,
					StandardCopyOption.REPLACE_EXISTING);
			}
			catch (AtomicMoveNotSupportedException e)
			{
				Files.move(temporary, file(groupId), StandardCopyOption.REPLACE_EXISTING);
			}
		}
		catch (IOException e)
		{
			// A cache failure must never turn a successful API response into a failed sync.
			log.warn("WOM Clan Stats: could not write cache for group {}: {}", groupId, e.getMessage());
		}
	}

	private Path file(int groupId)
	{
		return directory.resolve("group-" + groupId + ".json");
	}

	private static <T> WomHistory<T> parseHistory(String body, Parser<T> parser) throws IOException
	{
		return body == null || body.isEmpty() ? WomHistory.pending() : WomHistory.loaded(parser.parse(body));
	}

	private static long oldestPresent(long first, long second, long third)
	{
		if (first <= 0 || second <= 0 || third <= 0)
		{
			return 0;
		}
		return Math.min(first, Math.min(second, third));
	}

	@FunctionalInterface
	private interface Parser<T>
	{
		java.util.List<T> parse(String body) throws IOException;
	}

	@Value
	static class CachedClan
	{
		WomClanData data;
		long groupCachedAtMs;
		long historyCachedAtMs;

		boolean historyNeedsRefresh(long nowMs)
		{
			return historyCachedAtMs <= 0 || nowMs - historyCachedAtMs >= HISTORY_MAX_AGE_MS;
		}
	}

	private static class Record
	{
		private String groupBody;
		private long groupAtMs;
		private String achievementsBody;
		private long achievementsAtMs;
		private String activityBody;
		private long activityAtMs;
		private String nameChangesBody;
		private long nameChangesAtMs;
	}
}

package com.womclan;

import java.text.DecimalFormat;
import java.text.NumberFormat;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

/**
 * Pure formatting helpers shared by the sidebar panel and the expanded window.
 *
 * <p>Kept free of Swing so the display rules can be unit tested headlessly.</p>
 */
final class WomFormat
{
	private static final NumberFormat INTEGER_FORMAT = NumberFormat.getIntegerInstance(Locale.US);
	private static final DecimalFormat ABBREVIATED = new DecimalFormat("#.#");
	private static final String[] MAGNITUDES = {"", "K", "M", "B", "T"};

	/**
	 * Highest total level reachable in game. A "levels" threshold larger than this cannot be a
	 * level count, which is how the WOM API's base-stat achievements give themselves away: they
	 * carry an experience threshold while reporting a level measure.
	 */
	private static final long MAX_TOTAL_LEVEL = 2376L;

	private static final DateTimeFormatter TIME_OF_DAY = DateTimeFormatter.ofPattern("HH:mm", Locale.US);
	private static final DateTimeFormatter DATE_AND_TIME = DateTimeFormatter.ofPattern("d MMM HH:mm", Locale.US);
	private static final DateTimeFormatter FULL_TIMESTAMP = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss", Locale.US);
	private static final DateTimeFormatter SHORT_DATE = DateTimeFormatter.ofPattern("d MMM yyyy", Locale.US);
	private static final DateTimeFormatter EXACT_MOMENT = DateTimeFormatter.ofPattern("EEE d MMM yyyy, HH:mm", Locale.US);

	private WomFormat()
	{
	}

	static String integer(long value)
	{
		synchronized (INTEGER_FORMAT)
		{
			return INTEGER_FORMAT.format(value);
		}
	}

	static String integer(double value)
	{
		return integer(Math.round(value));
	}

	/** Formats a snake_case or lowercase API token as Title Case, e.g. {@code deputy_owner} → Deputy Owner. */
	static String titleCase(String token)
	{
		if (token == null || token.isEmpty())
		{
			return "";
		}

		StringBuilder sb = new StringBuilder();
		for (String word : token.replace('_', ' ').split(" "))
		{
			if (word.isEmpty())
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(' ');
			}
			sb.append(Character.toUpperCase(word.charAt(0)));
			sb.append(word.substring(1).toLowerCase(Locale.US));
		}
		return sb.toString();
	}

	/** Clan roles fall back to "Member" when the API omits one. */
	static String role(String role)
	{
		String formatted = titleCase(role);
		return formatted.isEmpty() ? "Member" : formatted;
	}

	/**
	 * Describes an achievement's threshold with a unit that actually matches the threshold.
	 *
	 * <p>The WOM API reports a {@code measure} alongside the raw {@code threshold}, but the two do
	 * not always agree: base-stat achievements ("Base 90 Stats") report a level measure with an
	 * experience threshold, which rendered as an absurd "128,311,968 levels". Rather than
	 * concatenating the two fields, an implausible level count is treated as the experience value
	 * it really is.</p>
	 *
	 * @return a human-readable description, or an empty string when there is nothing meaningful to show
	 */
	static String achievementValue(WomAchievement achievement)
	{
		long threshold = achievement.getThreshold();
		if (threshold <= 0)
		{
			return "";
		}

		String measure = achievement.getMeasure() == null ? "" : achievement.getMeasure().toLowerCase(Locale.US);
		if ("levels".equals(measure) && threshold > MAX_TOTAL_LEVEL)
		{
			measure = "experience";
		}

		switch (measure)
		{
			case "experience":
				return integer(threshold) + " XP";
			case "levels":
				return integer(threshold) + (threshold == 1 ? " level" : " levels");
			case "kills":
				return integer(threshold) + (threshold == 1 ? " kill" : " kills");
			case "score":
				return integer(threshold) + " score";
			case "":
				return integer(threshold);
			default:
				return integer(threshold) + " " + measure;
		}
	}

	/**
	 * Builds the secondary detail for an achievement, used as a tooltip so the metric and threshold
	 * stay available without repeating the milestone across three columns.
	 *
	 * @return the detail text, or {@code null} when the achievement name already says everything
	 */
	static String achievementDetail(WomAchievement achievement)
	{
		String metric = titleCase(achievement.getMetric());
		String value = achievementValue(achievement);

		if (metric.isEmpty() && value.isEmpty())
		{
			return null;
		}
		if (metric.isEmpty())
		{
			return value;
		}
		if (value.isEmpty())
		{
			return metric;
		}
		return metric + " — " + value;
	}

	/** Formats a remaining duration as {@code m:ss}, rounded up so it never reads 0:00 while waiting. */
	static String countdown(long remainingMs)
	{
		long seconds = (Math.max(0, remainingMs) + 999) / 1_000;
		return seconds / 60 + String.format(Locale.US, ":%02d", seconds % 60);
	}

	/**
	 * Describes how long ago something happened, in a form that stays true as time passes:
	 * an elapsed count while it is recent, an absolute clock time once "N mins ago" stops helping.
	 */
	static String since(long timestampMs, long nowMs)
	{
		return since(timestampMs, nowMs, ZoneId.systemDefault());
	}

	static String since(long timestampMs, long nowMs, ZoneId zone)
	{
		if (timestampMs <= 0)
		{
			return "never";
		}

		long minutes = Math.max(0, nowMs - timestampMs) / 60_000;
		if (minutes < 1)
		{
			return "just now";
		}
		if (minutes < 60)
		{
			return minutes + (minutes == 1 ? " min ago" : " mins ago");
		}

		ZonedDateTime then = Instant.ofEpochMilli(timestampMs).atZone(zone);
		ZonedDateTime now = Instant.ofEpochMilli(nowMs).atZone(zone);
		return then.toLocalDate().equals(now.toLocalDate())
			? "at " + TIME_OF_DAY.format(then)
			: "on " + DATE_AND_TIME.format(then);
	}

	/** The unabbreviated timestamp, for tooltips where the exact value has to stay discoverable. */
	static String timestamp(long timestampMs)
	{
		return timestamp(timestampMs, ZoneId.systemDefault());
	}

	static String timestamp(long timestampMs, ZoneId zone)
	{
		return timestampMs <= 0 ? "" : FULL_TIMESTAMP.format(Instant.ofEpochMilli(timestampMs).atZone(zone));
	}

	/**
	 * Explains the state of a history section in one line, so an API failure never masquerades as a
	 * clan with nothing going on.
	 *
	 * @param displayedRows rows actually on screen, which can be fewer than the fetched entries
	 * @param noun          plural noun for the section, e.g. "name changes"
	 */
	static String historyStatus(WomHistory.Status status, int fetchedRows, int visibleRows, String query, String noun)
	{
		switch (status)
		{
			case UNAVAILABLE:
				return "Could not load " + noun + ".";
			case LOADED:
				if (fetchedRows == 0)
				{
					return "No recent " + noun + ".";
				}
				if (query.isEmpty())
				{
					return "Showing " + integer(fetchedRows) + " recent " + noun + ".";
				}
				// A search that matches nothing is a different situation from a clan with no recent
				// events, and both differ again from a fetch that failed.
				return visibleRows == 0
					? "No " + noun + " match \"" + query + "\"."
					: "Showing " + integer(visibleRows) + " of " + integer(fetchedRows) + " recent " + noun + ".";
			default:
				return "Loading " + noun + "…";
		}
	}

	/**
	 * The label for a manual refresh control. The wait goes on the control itself because Swing
	 * hides tooltips on disabled components, and an enabled-looking button that refuses to refresh
	 * is worse than a labelled wait.
	 */
	static String syncButtonText(WomSyncStatus status, String idleText)
	{
		if (status.isFetching())
		{
			return "Syncing…";
		}
		return status.getCooldownRemainingMs() > 0
			? idleText + " in " + countdown(status.getCooldownRemainingMs())
			: idleText;
	}

	/**
	 * One line describing the refresh state, shared by every surface so they cannot disagree about
	 * how fresh the data is.
	 *
	 * @param hasData whether there is loaded data still on screen behind a failure
	 */
	static String syncSummary(WomSyncStatus status, boolean hasData, long nowMs)
	{
		if (status.isFetching())
		{
			return "Syncing…";
		}

		switch (status.getOutcome())
		{
			case NOT_CONFIGURED:
				return "Set your Group ID in settings";
			case FAILURE:
				if (hasData && status.hasSucceeded())
				{
					return (status.getServerBackoffRemainingMs() > 0 ? "Rate limited" : "Sync failed")
						+ " · showing data " + since(status.getLastSuccessMs(), nowMs);
				}
				return status.getCooldownRemainingMs() > 0
					? (status.getServerBackoffRemainingMs() > 0 ? "Rate limited" : "Sync failed")
						+ " · retry in " + countdown(status.getCooldownRemainingMs())
					: "Sync failed · retry available";
			case CACHED:
				return "Cached · updated " + since(status.getLastSuccessMs(), nowMs);
			case SUCCESS:
				return "Synced " + since(status.getLastSuccessMs(), nowMs);
			default:
				return "Not synced yet";
		}
	}

	/** Advanced request-budget detail for the status tooltip. */
	static String rateLimitSummary(WomSyncStatus status, long nowMs)
	{
		if (!status.hasRateLimit() || status.getRateResetAtMs() <= nowMs)
		{
			return null;
		}
		long resetMs = Math.max(0, status.getRateResetAtMs() - nowMs);
		return "WOM API: " + status.getRateRemaining() + "/" + status.getRateLimit()
			+ " requests remaining · resets in " + countdown(resetMs);
	}

	/**
	 * A compact relative date for history rows, coarsening as events get older. The exact moment
	 * stays available through {@link #exactMoment}.
	 */
	static String relative(Instant instant, long nowMs)
	{
		return relative(instant, nowMs, ZoneId.systemDefault());
	}

	static String relative(Instant instant, long nowMs, ZoneId zone)
	{
		if (instant == null)
		{
			return "";
		}

		long minutes = Math.max(0, nowMs - instant.toEpochMilli()) / 60_000;
		if (minutes < 1)
		{
			return "just now";
		}
		if (minutes < 60)
		{
			return minutes + "m ago";
		}

		long hours = minutes / 60;
		if (hours < 24)
		{
			return hours + "h ago";
		}

		long days = hours / 24;
		return days < 7 ? days + "d ago" : SHORT_DATE.format(instant.atZone(zone));
	}

	/** The full moment behind a relative date, for the hover tooltip. */
	static String exactMoment(Instant instant)
	{
		return exactMoment(instant, ZoneId.systemDefault());
	}

	static String exactMoment(Instant instant, ZoneId zone)
	{
		return instant == null ? "" : EXACT_MOMENT.format(instant.atZone(zone));
	}

	/**
	 * Shortens a large total so it fits the sidebar's narrow column, e.g. 25,600,000,000 as 25.6B.
	 * Callers pair this with {@link #integer} in a tooltip so the exact value stays discoverable.
	 */
	static String abbreviate(long value)
	{
		double scaled = value;
		int magnitude = 0;
		while (Math.abs(scaled) >= 1_000 && magnitude < MAGNITUDES.length - 1)
		{
			scaled /= 1_000;
			magnitude++;
		}

		// Rounding to one decimal can push a value back up a magnitude: 999,960 is "1000K" unless
		// it is promoted to "1M" here.
		if (Math.abs(Math.round(scaled * 10) / 10.0) >= 1_000 && magnitude < MAGNITUDES.length - 1)
		{
			scaled /= 1_000;
			magnitude++;
		}

		if (magnitude == 0)
		{
			return integer(value);
		}

		synchronized (ABBREVIATED)
		{
			return ABBREVIATED.format(scaled) + MAGNITUDES[magnitude];
		}
	}

	static String abbreviate(double value)
	{
		return abbreviate(Math.round(value));
	}

	/**
	 * Describes how much of the member list is on screen, so the search reports its own result
	 * count rather than leaving the user to guess whether it matched anything.
	 */
	static String memberCount(int visible, int total, String query)
	{
		if (total == 0)
		{
			return "";
		}
		if (query.isEmpty())
		{
			return integer(total) + (total == 1 ? " member" : " members");
		}
		return visible == 0
			? "No members match \"" + query + "\""
			: integer(visible) + " of " + integer(total) + " members";
	}
}

package com.womclan;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

import javax.inject.Inject;
import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.function.Consumer;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

@Slf4j
@PluginDescriptor(
	name = "WOM Clan Stats",
	description = "Displays Wise Old Man clan member stats (Total XP, EHP, EHB) in a sidebar panel",
	tags = {"wom", "clan", "xp", "ehb", "ehp", "wise old man", "hiscores"}
)
public class WomClanPlugin extends Plugin
{
	private static final int AUTO_REFRESH_MINUTES = 60;
	private static final String NETWORK_STATE_GROUP = "womclan.network";
	private static final String MANUAL_ALLOWED_AT_KEY = "manualAllowedAt";
	private static final String SERVER_RETRY_AT_KEY = "serverRetryAt";

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private WomClanConfig config;

	@Inject
	private WomApiClient apiClient;

	@Inject
	private ConfigManager configManager;

	@Inject
	private WomWindowGeometry windowGeometry;

	/** Restores and records the expanded window's size and position across openings. */
	WomWindowGeometry windowGeometry()
	{
		return windowGeometry;
	}

	private final WomSyncState syncState = new WomSyncState();

	private volatile WomClanPanel panel;
	private NavigationButton navButton;
	private ScheduledExecutorService executor;
	private ScheduledFuture<?> autoRefreshTask;
	private volatile WomClanData currentData;
	private volatile long historyCachedAtMs;

	@Override
	protected void startUp() throws Exception
	{
		syncState.restoreDeadlines(
			readDeadline(MANUAL_ALLOWED_AT_KEY),
			readDeadline(SERVER_RETRY_AT_KEY));
		panel = new WomClanPanel(this);
		restoreCachedData();

		navButton = NavigationButton.builder()
			.tooltip("WOM Clan Stats")
			.icon(buildIcon())
			.priority(7)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);

		executor = Executors.newSingleThreadScheduledExecutor();
		scheduleAutoRefresh();
	}

	@Override
	protected void shutDown() throws Exception
	{
		cancelAutoRefresh();

		if (executor != null)
		{
			executor.shutdownNow();
			executor = null;
		}

		clientToolbar.removeNavigation(navButton);

		if (panel != null)
		{
			panel.shutdown();
			panel = null;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!"womclan".equals(event.getGroup()))
		{
			return;
		}

		// A different group invalidates everything on screen, including the "last synced" time:
		// leaving the old clan's members visible under the new group's name would be a lie.
		boolean groupChanged = "groupId".equals(event.getKey());
		if (groupChanged)
		{
			syncState.reset();
			currentData = null;
			historyCachedAtMs = 0;
			WomClanCache.CachedClan cached = isGroupConfigured()
				? apiClient.loadCachedClanData(config.groupId()) : null;
			if (cached != null)
			{
				currentData = cached.getData();
				historyCachedAtMs = cached.getHistoryCachedAtMs();
				syncState.recordCached(cached.getGroupCachedAtMs());
			}
			onPanel(panel ->
			{
				panel.clearClanData();
				panel.setGroupConfigured(isGroupConfigured());
				if (cached != null)
				{
					panel.updateClanData(cached.getData());
				}
			});
		}

		// Re-schedule whenever groupId or autoRefresh toggle changes
		cancelAutoRefresh();
		scheduleAutoRefresh();

		// scheduleAutoRefresh fetches straight away when it is enabled. With it turned off, a group
		// change still deserves one fetch, so setup does not hand back an empty panel.
		if (groupChanged && isGroupConfigured() && !config.autoRefresh())
		{
			requestManualSync();
		}
	}

	/**
	 * Called by the panel's Sync Now button. Does nothing when a fetch is already running or the
	 * manual cooldown has not elapsed; callers read {@link #syncStatus()} to explain why.
	 */
	void requestManualSync()
	{
		if (executor == null || executor.isShutdown())
		{
			return;
		}

		if (syncState.beginManualFetch(System.currentTimeMillis()))
		{
			persistNetworkGate();
			executor.submit(this::fetchAndUpdate);
		}
	}

	/** Loads stale or missing detail feeds on demand when the expanded window is opened. */
	void requestHistorySync()
	{
		long now = System.currentTimeMillis();
		WomClanData base = currentData;
		if (base == null || executor == null || executor.isShutdown()
			|| historyCachedAtMs > 0 && now - historyCachedAtMs < WomClanCache.HISTORY_MAX_AGE_MS)
		{
			return;
		}

		if (syncState.beginAutoFetch(now))
		{
			executor.submit(() -> fetchHistoryAndUpdate(base));
			onPanel(WomClanPanel::refreshSyncStatus);
		}
	}

	boolean isGroupConfigured()
	{
		return config.groupId() > 0;
	}

	/**
	 * Stores a group id chosen from the panel's setup state. Writing through ConfigManager keeps the
	 * plugin's own settings the single source of truth, and the resulting ConfigChanged drives the
	 * panel out of setup and into its first fetch.
	 */
	void setGroupId(int groupId)
	{
		configManager.setConfiguration("womclan", "groupId", groupId);
	}

	/** The current refresh state, shared by every surface that offers a refresh. */
	WomSyncStatus syncStatus()
	{
		return syncState.snapshot(System.currentTimeMillis());
	}

	// ── Private helpers ────────────────────────────────────────────────────────

	private void scheduleAutoRefresh()
	{
		if (!config.autoRefresh() || executor == null || executor.isShutdown())
		{
			return;
		}

		// Fetch immediately on startup / config change, then every 60 min
		autoRefreshTask = executor.scheduleAtFixedRate(
			this::autoFetch,
			0, AUTO_REFRESH_MINUTES, TimeUnit.MINUTES
		);
	}

	private void cancelAutoRefresh()
	{
		if (autoRefreshTask != null)
		{
			autoRefreshTask.cancel(false);
			autoRefreshTask = null;
		}
	}

	private void autoFetch()
	{
		// A scheduled refresh that lands on top of a running one is simply skipped; it must not
		// touch the manual cooldown either way.
		if (syncState.beginAutoFetch(System.currentTimeMillis()))
		{
			fetchAndUpdate();
		}
	}

	private void fetchAndUpdate()
	{
		int groupId = config.groupId();

		if (groupId <= 0)
		{
			syncState.recordNotConfigured();
			onPanel(WomClanPanel::refreshSyncStatus);
			return;
		}

		onPanel(WomClanPanel::refreshSyncStatus);

		try
		{
			WomClanData clanData = apiClient.fetchClanData(groupId);
			currentData = clanData;
			WomClanCache.CachedClan cached = apiClient.loadCachedClanData(groupId);
			historyCachedAtMs = cached == null ? 0 : cached.getHistoryCachedAtMs();
			syncState.recordSuccess(System.currentTimeMillis());
			onPanel(p ->
			{
				p.updateClanData(clanData);
				// Opening Details during this fetch could not claim the shared request gate. Once
				// overview loading finishes, satisfy that still-visible window on demand.
				if (p.isDetailsVisible())
				{
					requestHistorySync();
				}
			});
		}
		catch (IOException e)
		{
			log.warn("WOM Clan Stats: failed to fetch group {}: {}", groupId, e.getMessage());
			syncState.recordFailure(e.getMessage());
			onPanel(p -> p.showError(e.getMessage()));
		}
		finally
		{
			applyAndPersistRateLimit();
		}
	}

	private void fetchHistoryAndUpdate(WomClanData requestedBase)
	{
		try
		{
			WomClanData latest = currentData;
			if (latest == null || latest.getGroupId() != requestedBase.getGroupId())
			{
				syncState.recordFailure("Clan changed while loading details");
				return;
			}

			WomClanData updated = apiClient.fetchClanHistory(latest.getGroupId(), latest);
			currentData = updated;
			WomClanCache.CachedClan cached = apiClient.loadCachedClanData(latest.getGroupId());
			historyCachedAtMs = cached == null ? 0 : cached.getHistoryCachedAtMs();
			syncState.recordSuccess(System.currentTimeMillis());
			onPanel(p -> p.updateClanData(updated));
		}
		catch (IOException e)
		{
			log.warn("WOM Clan Stats: failed to fetch clan details: {}", e.getMessage());
			syncState.recordFailure(e.getMessage());
			onPanel(p -> p.showError(e.getMessage()));
		}
		finally
		{
			applyAndPersistRateLimit();
		}
	}

	private void restoreCachedData()
	{
		int groupId = config.groupId();
		if (groupId <= 0)
		{
			return;
		}

		WomClanCache.CachedClan cached = apiClient.loadCachedClanData(groupId);
		if (cached == null)
		{
			return;
		}

		currentData = cached.getData();
		historyCachedAtMs = cached.getHistoryCachedAtMs();
		syncState.recordCached(cached.getGroupCachedAtMs());
		panel.updateClanData(currentData);
	}

	private void applyAndPersistRateLimit()
	{
		syncState.applyRateLimit(apiClient.rateLimitStatus());
		persistNetworkGate();
		onPanel(WomClanPanel::refreshSyncStatus);
	}

	private long readDeadline(String key)
	{
		String value = configManager.getConfiguration(NETWORK_STATE_GROUP, key);
		if (value == null)
		{
			return 0;
		}
		try
		{
			return Long.parseLong(value);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	private void persistNetworkGate()
	{
		configManager.setConfiguration(NETWORK_STATE_GROUP, MANUAL_ALLOWED_AT_KEY,
			Long.toString(syncState.getManualAllowedAtMs()));
		configManager.setConfiguration(NETWORK_STATE_GROUP, SERVER_RETRY_AT_KEY,
			Long.toString(syncState.getServerRetryAtMs()));
	}

	/** Runs a panel update on the EDT, skipping it if the plugin shut down in the meantime. */
	private void onPanel(Consumer<WomClanPanel> action)
	{
		SwingUtilities.invokeLater(() ->
		{
			WomClanPanel current = panel;
			if (current != null)
			{
				action.accept(current);
			}
		});
	}

	/** Creates a small 16×16 icon programmatically (blue rounded square with "W"). */
	private BufferedImage buildIcon()
	{
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// Background
		g.setColor(new Color(30, 130, 200));
		g.fillRoundRect(0, 0, 15, 15, 5, 5);

		// "W" letter
		g.setColor(Color.WHITE);
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 10));
		FontMetrics fm = g.getFontMetrics();
		String letter = "W";
		int x = (16 - fm.stringWidth(letter)) / 2;
		int y = (16 - fm.getHeight()) / 2 + fm.getAscent();
		g.drawString(letter, x, y);
		g.dispose();

		return img;
	}

	@Provides
	WomClanConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(WomClanConfig.class);
	}
}

